args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?father ?fatherLabel (COALESCE(?death1, ?death2) AS ?deathDate) WHERE {
  VALUES (?sub) { (dbr:Julia_Livia) }
  # get father via common properties
  ?sub (dbp:father|dbo:parent) ?father .
  OPTIONAL { ?father dbp:deathDate ?death1. }
  OPTIONAL { ?father dbo:deathDate ?death2. }
  OPTIONAL { ?father rdfs:label ?fatherLabel. FILTER(lang(?fatherLabel) = "en") }
}

